import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry conv_transpose2d_kernel(
    .param .u64 in_ptr,
    .param .u64 weight_ptr,
    .param .u64 out_ptr,
    .param .u64 bias_ptr,
    .param .u32 N,
    .param .u32 C_in,
    .param .u32 C_out,
    .param .u32 H_in,
    .param .u32 W_in,
    .param .u32 H_out,
    .param .u32 W_out,
    .param .u32 kH,
    .param .u32 kW,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 groups,
    .param .u32 c_in_per_group,
    .param .u32 c_out_per_group,
    .param .u32 has_bias
)
{
    .reg .pred p0, p1, p2;
    .reg .b32 r_idx, r_total, r_tmp0, r_tmp1, r_tmp2;
    .reg .b32 r_N, r_Cin, r_Cout, r_Hin, r_Win, r_Hout, r_Wout, r_kH, r_kW;
    .reg .b32 r_strideh, r_stridew, r_padh, r_padw, r_dilh, r_dilw;
    .reg .b32 r_groups, r_cinpg, r_coutpg, r_hasbias;
    .reg .b32 r_x, r_y, r_co, r_n, r_g, r_cog, r_ci_start, r_ci_end, r_ci;
    .reg .b32 r_kh, r_kw, r_iy, r_ix, r_iny, r_inx, r_mod, r_mod2;
    .reg .b32 t0, t1, t2, t3, t4, t5, t6;

    .reg .b64 inp, wp, outp, bp;
    .reg .b64 addr, addr2, addr3;
    .reg .f32 f_acc, f_in, f_w, f_b;

    // Load pointers
    ld.param.u64  inp,   [in_ptr];
    ld.param.u64  wp,    [weight_ptr];
    ld.param.u64  outp,  [out_ptr];
    ld.param.u64  bp,    [bias_ptr];

    // Load scalars
    ld.param.u32  r_N,       [N];
    ld.param.u32  r_Cin,     [C_in];
    ld.param.u32  r_Cout,    [C_out];
    ld.param.u32  r_Hin,     [H_in];
    ld.param.u32  r_Win,     [W_in];
    ld.param.u32  r_Hout,    [H_out];
    ld.param.u32  r_Wout,    [W_out];
    ld.param.u32  r_kH,      [kH];
    ld.param.u32  r_kW,      [kW];
    ld.param.u32  r_strideh, [stride_h];
    ld.param.u32  r_stridew, [stride_w];
    ld.param.u32  r_padh,    [pad_h];
    ld.param.u32  r_padw,    [pad_w];
    ld.param.u32  r_dilh,    [dil_h];
    ld.param.u32  r_dilw,    [dil_w];
    ld.param.u32  r_groups,  [groups];
    ld.param.u32  r_cinpg,   [c_in_per_group];
    ld.param.u32  r_coutpg,  [c_out_per_group];
    ld.param.u32  r_hasbias, [has_bias];

    // Compute global linear thread index
    .reg .b32 r_tid, r_cta, r_ntid;
    mov.u32 r_tid,  %tid.x;
    mov.u32 r_cta,  %ctaid.x;
    mov.u32 r_ntid, %ntid.x;
    mad.lo.u32 r_idx, r_cta, r_ntid, r_tid;

    // total_out = N * C_out * H_out * W_out
    mul.lo.u32 r_tmp0, r_N, r_Cout;
    mul.lo.u32 r_tmp1, r_Hout, r_Wout;
    mul.lo.u32 r_total, r_tmp0, r_tmp1;

    setp.ge.u32 p0, r_idx, r_total;
    @p0 bra DONE;

    // Decode linear index into (n, co, y, x)
    // x = idx % W_out
    rem.u32 r_x, r_idx, r_Wout;
    // tmp = idx / W_out
    div.u32 r_tmp0, r_idx, r_Wout;
    // y = tmp % H_out
    rem.u32 r_y, r_tmp0, r_Hout;
    // tmp2 = tmp / H_out
    div.u32 r_tmp1, r_tmp0, r_Hout;
    // co = tmp2 % C_out
    rem.u32 r_co, r_tmp1, r_Cout;
    // n = tmp2 / C_out
    div.u32 r_n, r_tmp1, r_Cout;

    // group g = co / c_out_per_group
    div.u32 r_g, r_co, r_coutpg;
    // co_in_group = co - g * c_out_per_group
    mul.lo.u32 t0, r_g, r_coutpg;
    sub.s32 r_cog, r_co, t0;

    // ci range
    mul.lo.u32 r_ci_start, r_g, r_cinpg;
    add.u32 r_ci_end, r_ci_start, r_cinpg;

    // Initialize accumulator
    mov.f32 f_acc, 0f00000000;

    // If has_bias, load bias[co]
    setp.eq.u32 p0, r_hasbias, 0;
    @p0 bra SKIP_BIAS;
        mul.wide.u32 addr, r_co, 4;
        add.u64 addr, bp, addr;
        ld.global.f32 f_b, [addr];
        mov.f32 f_acc, f_b;
SKIP_BIAS:

    // Loop over kh
    mov.u32 r_kh, 0;
KH_LOOP:
    setp.ge.u32 p0, r_kh, r_kH;
    @p0 bra AFTER_KH;

    // in_y_idx = (int)y + pad_h - kh * dil_h
    mul.lo.u32 t1, r_kh, r_dilh;
    add.u32 t2, r_y, r_padh;
    sub.s32 r_iny, t2, t1;

    // if (r_iny % stride_h != 0) continue
    rem.s32 r_mod, r_iny, r_strideh;
    setp.ne.s32 p0, r_mod, 0;
    @p0 bra NEXT_KH;

    // iy = r_iny / stride_h
    div.s32 r_iy, r_iny, r_strideh;
    setp.lt.s32 p0, r_iy, 0;
    @p0 bra NEXT_KH;
    setp.ge.s32 p0, r_iy, r_Hin;
    @p0 bra NEXT_KH;

    // Loop over kw
    mov.u32 r_kw, 0;
KW_LOOP:
    setp.ge.u32 p0, r_kw, r_kW;
    @p0 bra AFTER_KW;

    // in_x_idx = (int)x + pad_w - kw * dil_w
    mul.lo.u32 t3, r_kw, r_dilw;
    add.u32 t4, r_x, r_padw;
    sub.s32 r_inx, t4, t3;

    // if (r_inx % stride_w != 0) continue
    rem.s32 r_mod2, r_inx, r_stridew;
    setp.ne.s32 p0, r_mod2, 0;
    @p0 bra NEXT_KW;

    // ix = r_inx / stride_w
    div.s32 r_ix, r_inx, r_stridew;
    setp.lt.s32 p0, r_ix, 0;
    @p0 bra NEXT_KW;
    setp.ge.s32 p0, r_ix, r_Win;
    @p0 bra NEXT_KW;

    // Loop over ci in group
    mov.u32 r_ci, r_ci_start;
CI_LOOP:
    setp.ge.u32 p0, r_ci, r_ci_end;
    @p0 bra AFTER_CI;

    // Load input[n, ci, iy, ix]
    mul.lo.u32 t0, r_n, r_Cin;       // n * C_in
    add.u32   t0, t0, r_ci;          // + ci
    mul.lo.u32 t0, t0, r_Hin;        // * H_in
    add.u32   t0, t0, r_iy;          // + iy
    mul.lo.u32 t0, t0, r_Win;        // * W_in
    add.u32   t0, t0, r_ix;          // + ix
    mul.wide.u32 addr2, t0, 4;       // * sizeof(float)
    add.u64  addr2, inp, addr2;
    ld.global.f32 f_in, [addr2];

    // Load weight[ci, co_in_group, kh, kw]
    mul.lo.u32 t1, r_ci, r_coutpg;   // ci * C_out_per_group
    add.u32   t1, t1, r_cog;         // + co_in_group
    mul.lo.u32 t1, t1, r_kH;         // * kH
    add.u32   t1, t1, r_kh;          // + kh
    mul.lo.u32 t1, t1, r_kW;         // * kW
    add.u32   t1, t1, r_kw;          // + kw
    mul.wide.u32 addr3, t1, 4;
    add.u64  addr3, wp, addr3;
    ld.global.f32 f_w, [addr3];

    // FMA
    fma.rn.f32 f_acc, f_in, f_w, f_acc;

    add.u32 r_ci, r_ci, 1;
    bra CI_LOOP;
AFTER_CI:

NEXT_KW:
    add.u32 r_kw, r_kw, 1;
    bra KW_LOOP;
AFTER_KW:

NEXT_KH:
    add.u32 r_kh, r_kh, 1;
    bra KH_LOOP;
AFTER_KH:

    // Store out[n, co, y, x]
    mul.lo.u32 t5, r_n, r_Cout;    // n * C_out
    add.u32   t5, t5, r_co;        // + co
    mul.lo.u32 t5, t5, r_Hout;     // * H_out
    add.u32   t5, t5, r_y;         // + y
    mul.lo.u32 t5, t5, r_Wout;     // * W_out
    add.u32   t5, t5, r_x;         // + x
    mul.wide.u32 addr, t5, 4;
    add.u64  addr, outp, addr;
    st.global.f32 [addr], f_acc;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose2d_kernel")

class ModelNew(nn.Module):
    """
    Performs a 2D transposed convolution operation with asymmetric input, asymmetric kernel, 
    grouped, padded, and dilated using a single custom PTX kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        self.conv_transpose2d = nn.ConvTranspose2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        weight = self.conv_transpose2d.weight
        bias = self.conv_transpose2d.bias
        # Ensure tensors are contiguous (expected in standard usage)
        assert x.is_contiguous(), "Input must be contiguous"
        assert weight.is_contiguous(), "Weight must be contiguous"
        if bias is not None:
            assert bias.is_contiguous(), "Bias must be contiguous"

        N, C_in, H_in, W_in = x.shape
        C_out = self.conv_transpose2d.out_channels
        kH, kW = self.conv_transpose2d.kernel_size
        sH, sW = self.conv_transpose2d.stride
        pH, pW = self.conv_transpose2d.padding
        dH, dW = self.conv_transpose2d.dilation
        groups = self.conv_transpose2d.groups

        # Output dimensions for ConvTranspose2d with output_padding=0
        H_out = (H_in - 1) * sH - 2 * pH + dH * (kH - 1) + 1
        W_out = (W_in - 1) * sW - 2 * pW + dW * (kW - 1) + 1

        out = torch.empty((N, C_out, H_out, W_out), device=x.device, dtype=x.dtype)

        cin_per_group = C_in // groups
        cout_per_group = C_out // groups
        has_bias = 1 if bias is not None else 0
        bias_tensor = bias if bias is not None else torch.empty(1, device=x.device, dtype=x.dtype)

        total = N * C_out * H_out * W_out
        block_x = 128
        grid_x = (total + block_x - 1) // block_x

        module = _get_ptx_module()
        module.launch(
            "conv_transpose2d_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x,
                weight,
                out,
                bias_tensor,
                i32(N),
                i32(C_in),
                i32(C_out),
                i32(H_in),
                i32(W_in),
                i32(H_out),
                i32(W_out),
                i32(kH),
                i32(kW),
                i32(sH),
                i32(sW),
                i32(pH),
                i32(pW),
                i32(dH),
                i32(dW),
                i32(groups),
                i32(cin_per_group),
                i32(cout_per_group),
                i32(has_bias),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

